// def __init__(self, w: int32) -> None:
//     self.w = w
inline Inner::Inner(int32_t w) : w(w) {}

// def __init__(self, v: int32) -> None:
//     self.v = v
//     self.inner = Inner(v * 10)
inline Cell::Cell(int32_t v)
    : v(v),
      inner(Inner((::tpy::mul_check<int32_t>(v, 10)))) {}

// def __init__(self, c: Ptr[Cell]) -> None:
//     self.c = c
inline Holder::Holder(Cell* c) : c(c) {}

// def __init__(self) -> None:
//     self.cells = [Cell(11), Cell(22)]
//     self.i = 0
inline Feed::Feed()
    : cells(std::vector<Cell>{Cell(11), Cell(22)}),
      i(0) {}

// def __iter__(self) -> "Feed":
//     return self
inline Feed& Feed::__iter__() {
    return (*this);
}

// def __next__(self) -> Cell:
//     if self.i >= len(self.cells):
//         raise StopIteration()
//     c = self.cells[self.i]
//     self.i += 1
//     return c
inline std::expected<::tpy::val_or_ref<Cell>, ::tpy::StopIteration> Feed::__next__() {
    if ((this->i >= ::tpy::__len__(this->cells))) {
        return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    Cell& c = ::tpy::__getitem__(this->cells, this->i);
    this->i = ::tpy::add_check<int32_t>(this->i, 1);
    return c;
}

// def __init__(self) -> None:
//     self.cells = [Cell(11), Cell(22)]
inline Bag::Bag() : cells(std::vector<Cell>{Cell(11), Cell(22)}) {}

// def __enter__(self) -> int32:
//     return 1
inline int32_t Scope::__enter__() const {
    return 1;
}

